  "unearth": {"rule":"702.84a","pattern":"Unearth [cost]","meaning":["[Cost]: Return this card from your graveyard to the battlefield. It gains haste. Exile it at the beginning of the next end step. If it would leave the battlefield, exile it instead of putting it anywhere else. Activate only as a sorcery."],"zone":"graveyard"},
  "unleash": {"rule":"702.98a","pattern":"Unleash","meaning":["You may have this permanent enter with an additional +1/+1 counter on it.","This permanent can't block as long as it has a +1/+1 counter on it."]},
  "vanishing": {"rule":"702.63a","pattern":"Vanishing N","meaning":["This permanent enters with N time counters on it.","At the beginning of your upkeep, if this permanent has a time counter on it, remove a time counter from it.","When the last time counter is removed from this permanent, sacrifice it."]},
