  "warp": {"rule":"702.185a","pattern":"Warp [cost]","meaning":["You may cast this card from your hand by paying [cost] rather than its mana cost.","If this spell's warp cost was paid, exile the permanent this spell becomes at the beginning of the next end step. Its owner may cast this card after the current turn has ended for as long as it remains exiled."]},
